SELECT id, user_id, session_id, role, content, created_at
FROM chat_history
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit}

SELECT id, user_id, session_id, role, content, created_at
FROM chat_history
WHERE user_id = #{userId}
  AND content ILIKE '%' || #{keyword} || '%'
ORDER BY created_at DESC
LIMIT #{limit}
